    },
    {
      "hunk_id": "H020",
      "decision": "SOL",
      "reason": "“Shared his qi” preserves the energy given without hesitation."
    },
    {
      "hunk_id": "H021",
      "decision": "SOL",
      "reason": "“Wounds large and small covered his body” keeps the source’s range of injuries."
    },
    {
      "hunk_id": "H022",
      "decision": "SOL",
      "reason": "Naming Jeok Cheongang directly preserves the subject and avoids needless apposition."
    },
    {
      "hunk_id": "H023",
      "decision": "SOL",
      "reason": "SOL makes explicit that he suppresses both the joy and the sorrow."
    },
    {
      "hunk_id": "H024",
      "decision": "SOL",
      "reason": "SOL preserves time starting again and the step forward without changing the sequence."
    },
    {
      "hunk_id": "H025",
      "decision": "SOL",
      "reason": "“My fight alone” keeps the hypothetical solitude and the possibility of giving up."
    },
    {
      "hunk_id": "H026",
      "decision": "BASE",
      "reason": "“Looked back on my life” narrows the source’s reflection on the time he had lived through."
    },
    {
      "hunk_id": "H027",
      "decision": "BASE",
      "reason": "The source describes the earth itself as reddish and heated; SOL changes this to a reddish glow."
    },
    {
      "hunk_id": "H028",
      "decision": "SOL",
      "reason": "“Advanced” carries the group’s movement into the scene without changing who is present."
    },
    {
      "hunk_id": "H029",
      "decision": "SOL",
      "reason": "The civilians are retained in the following sentence, so deleting this separate fragment loses no content."
    },
    {
      "hunk_id": "H030",
      "decision": "SOL",
      "reason": "SOL retains the civilians following like a wave and their shift from desperate cries to calling a name."
    },
    {
      "hunk_id": "H031",
      "decision": "SOL",
      "reason": "“A jolt like lightning” preserves the sudden bodily shiver without implying literal lightning."
    },
    {
      "hunk_id": "H032",
      "decision": "SOL",
      "reason": "SOL keeps both their lack of internal energy and proper weapons, as well as the tools they grip."
    },
    {
      "hunk_id": "H033",
      "decision": "SOL",
      "reason": "SOL preserves the faces flashing through his mind and his charge toward the fanatics."
    },
    {
      "hunk_id": "H034",
      "decision": "SOL",
      "reason": "“My toes” naturally renders the listed point of the foot and keeps the movement sequence."
    },
    {
      "hunk_id": "H035",
      "decision": "SOL",
      "reason": "SOL keeps the instinctive movements and the wind and rain being split."
    },
    {
      "hunk_id": "H036",
      "decision": "SOL",
      "reason": "“Crossed the air” preserves the cutting sound sweeping through the space."
    },
    {
      "hunk_id": "H037",
      "decision": "SOL",
      "reason": "“Slit throats” naturally preserves the fanatics clutching their cut throats as they fall."
    },
    {
      "hunk_id": "H038",
      "decision": "BASE",
      "reason": "SOL drops that the enemies could not react “in time,” a meaningful detail of their failed response."
    },
    {
      "hunk_id": "H039",
      "decision": "SOL",
      "reason": "SOL keeps the next wave’s inability to react as it fills the gaps."
    },
    {
      "hunk_id": "H040",
      "decision": "SOL",
      "reason": "“Kept close” naturally conveys that he always carried the saber on his person."
    },
    {
      "hunk_id": "H041",
      "decision": "SOL",
      "reason": "“Rough appearance” makes explicit the contrast with his character while keeping the source’s sense."
    },
    {
      "hunk_id": "H042",
      "decision": "SOL",
      "reason": "The pronoun still clearly refers to Song Ilseom, and SOL preserves his complaints and where he fought."
    },
    {
      "hunk_id": "H043",
      "decision": "SOL",
      "reason": "“To protect someone” preserves the purpose for which he left the path he had followed."
    },
    {
      "hunk_id": "H044",
      "decision": "SOL",
      "reason": "SOL preserves the speaker’s confidence in the person he knew, using his name for clarity."
    },
    {
      "hunk_id": "H045",
      "decision": "BASE",
      "reason": "“Come to know” weakens the source’s meaningful ties with the two unorthodox faction members."
    },
    {
      "hunk_id": "H046",
      "decision": "SOL",
      "reason": "SOL preserves that the answer was sincerely meant and contained no lie."
    },
    {
      "hunk_id": "H047",
      "decision": "SOL",
      "reason": "“Wrestling with his choices” preserves the struggle and the long detour."
    },
    {
      "hunk_id": "H048",
      "decision": "SOL",
      "reason": "“The words echoed” naturally carries the persistent inward muttering."
    },
    {
      "hunk_id": "H049",
      "decision": "SOL",
      "reason": "“Ended my enemies’ lives” keeps the lethal result of Sama Pyo’s cruel, sure methods."
    },
    {
      "hunk_id": "H050",
      "decision": "SOL",
      "reason": "SOL retains the hallucination-like voices among the battle’s blood and screams."
    },
    {
      "hunk_id": "H051",
      "decision": "SOL",
      "reason": "SOL preserves familiar faces appearing over the enemies as they collapse."
    },
    {
      "hunk_id": "H052",
      "decision": "SOL",
      "reason": "“The memories” clarifies what rises like mist and passes like wind from the surrounding context."
    },
    {
      "hunk_id": "H053",
      "decision": "SOL",
      "reason": "The source’s darkness is preserved without the baseline’s added intensifier “deep.”"
    },
    {
      "hunk_id": "H054",
      "decision": "SOL",
      "reason": "“Buoyed by drink” keeps the sense of her steps and voice being aided by intoxication."
    },
    {
      "hunk_id": "H055",
      "decision": "SOL",
      "reason": "SOL keeps the wet, tearful eyes that the surrounding circumstances could not conceal."
    },
    {
      "hunk_id": "H056",
      "decision": "SOL",
      "reason": "SOL retains the vivid recollection without changing its emphasis."
    },
    {
      "hunk_id": "H057",
      "decision": "SOL",
      "reason": "SOL preserves both the fuss about the moon and his silence at her unexpected question."
    },
    {
      "hunk_id": "H058",
      "decision": "SOL",
      "reason": "“Spoken” naturally renders opening his mouth to speak while retaining her tear-filled eyes."
    },
    {
      "hunk_id": "H059",
      "decision": "BASE",
      "reason": "The source reassures her that it is all right even if she cannot do well; SOL shifts this to the outcome."
    },
    {
      "hunk_id": "H060",
      "decision": "SOL",
      "reason": "SOL naturally preserves the comparison between her eyes, the full moon, and a crescent."
    },
    {
      "hunk_id": "H061",
      "decision": "SOL",
      "reason": "SOL keeps both the unforeseen day and the pitch-black Force rushing toward him."
    },
    {
      "hunk_id": "H062",
      "decision": "BASE",
      "reason": "The source says the rushing sound swallowed the surrounding noise; SOL instead makes it swallow Jeok Cheongang’s shout."
    },
    {
      "hunk_id": "H063",
      "decision": "SOL",
      "reason": "“Even that much reason” preserves the source’s point that he lacked the capacity to react."
    },
    {
      "hunk_id": "H064",
      "decision": "SOL",
      "reason": "SOL keeps the two streams’ murkiness and their seeming lack of life without adding a comparison."
    },
    {
      "hunk_id": "H065",
      "decision": "SOL",
      "reason": "The preceding clause already establishes simultaneity, so SOL removes a redundant connector."
    },
    {
      "hunk_id": "H066",
      "decision": "SOL",
      "reason": "SOL keeps the key image of shattering and gives it natural emphasis."
    },
    {
      "hunk_id": "H067",
      "decision": "SOL",
      "reason": "“Inexplicable” preserves the speaker’s inability to understand what he did."
    },
    {
      "hunk_id": "H068",
      "decision": "BASE",
      "reason": "“So complete” omits the source’s explicit image of a perfect shattering."
    },
    {
      "hunk_id": "H069",
      "decision": "SOL",
      "reason": "“The last two” preserves that only two Black Ghosts remained."
    },
    {
      "hunk_id": "H070",
      "decision": "BASE",
      "reason": "“Crossed” drops the ghostly horse’s leap across the open air."
    },
    {
      "hunk_id": "H071",
      "decision": "SOL",
      "reason": "SOL preserves the blast’s violence and the already-burst eardrums being shaken."
    },
    {
      "hunk_id": "H072",
      "decision": "SOL",
      "reason": "“In its path” naturally preserves that others besides him were where the attackers were headed."
    },
    {
      "hunk_id": "H073",
      "decision": "SOL",
      "reason": "“Tangled” preserves the four streaks becoming intertwined in midair."
    },
    {
      "hunk_id": "H074",
      "decision": "SOL",
      "reason": "SOL keeps the air exploding and the earth overturning under the force."
    },
    {
      "hunk_id": "H075",
      "decision": "SOL",
      "reason": "The tense change does not alter the two superhumans’ rush to save him."
    },
    {
      "hunk_id": "H076",
      "decision": "SOL",
      "reason": "“Pierced and sliced” preserves the weapons’ actions against the Black Ghosts."
    },
    {
      "hunk_id": "H077",
      "decision": "SOL",
      "reason": "SOL reorders the linked actions clearly while preserving the Saints’ exhaustion and the Black Ghosts’ refusal to fall."
    },
    {
      "hunk_id": "H078",
      "decision": "SOL",
      "reason": "The Black Ghosts’ refusal to fall is retained in the preceding SOL hunk."
    },
    {
      "hunk_id": "H079",
      "decision": "SOL",
      "reason": "“After dozens of deaths” preserves their repeated deaths and returns."
    },
    {
      "hunk_id": "H080",
      "decision": "SOL",
      "reason": "SOL preserves the spells’ effects on healing, strength, and speed."
    },
    {
      "hunk_id": "H081",
      "decision": "BASE",
      "reason": "“Closer to their limits than anyone else” is an unsupported comparison; the source says they had reached their deepest limits."
    },
    {
      "hunk_id": "H082",
      "decision": "BASE",
      "reason": "“Fell on my cheek” loses the source’s image of the gaze touching his cheek."
    },
    {
      "hunk_id": "H083",
      "decision": "SOL",
      "reason": "“Supposed to die” keeps the sense that this was not his place to fall."
    },
    {
      "hunk_id": "H084",
      "decision": "SOL",
      "reason": "The thought about the promise is retained in the next SOL hunk, and “opened a path” preserves the leaders’ action."
    },
    {
      "hunk_id": "H085",
      "decision": "SOL",
      "reason": "SOL restores the source’s thought about the unkeepable promise in a complete sentence."
    },
    {
      "hunk_id": "H086",
      "decision": "SOL",
      "reason": "“My greatest memory in this world” naturally preserves the importance of the person and the moment."
    },
    {
      "hunk_id": "H087",
      "decision": "SOL",
      "reason": "SOL preserves the difficult first meeting without imposing a literal “feud.”"
    },
    {
      "hunk_id": "H088",
      "decision": "SOL",
      "reason": "The omitted “together” is already conveyed by the two of them falling into step."
    },
    {
      "hunk_id": "H089",
      "decision": "SOL",
      "reason": "Dropping “And” keeps the transition while avoiding a needless connective."
    },
    {
      "hunk_id": "H090",
      "decision": "SOL",
      "reason": "“Being apart no longer felt right” preserves their closeness in natural English."
    },
    {
      "hunk_id": "H091",
      "decision": "BASE",
      "reason": "“When I sent him away” adds the speaker’s agency; the source only says he worried when separated from him."
    },
    {
      "hunk_id": "H092",
      "decision": "SOL",
      "reason": "SOL clearly preserves that he never saw where or by whom Hyuk Mujin died."
    },
    {
      "hunk_id": "H093",
      "decision": "SOL",
      "reason": "SOL preserves the hypothetical miracle and the certainty they would never meet again."
    },
    {
      "hunk_id": "H094",
      "decision": "SOL",
      "reason": "“I would die before it could be” preserves that he would die before the promise could be fulfilled."
    },
    {
      "hunk_id": "H095",
      "decision": "BASE",
      "reason": "The source presents the waiting people as an alternative with “or”; SOL changes that to “and.”"
    },
    {
      "hunk_id": "H096",
      "decision": "SOL",
      "reason": "“Without pause” preserves the tireless rekindling of the dying flame."
    },
    {
      "hunk_id": "H097",
      "decision": "BASE",
      "reason": "The source says the blood was spurting upward; SOL changes its physical direction to beneath his feet."
    },
    {
      "hunk_id": "H098",
      "decision": "SOL",
      "reason": "SOL preserves the final, sole path for both the living and the dead."
    },
    {
      "hunk_id": "H099",
      "decision": "SOL",
      "reason": "“Clearly” preserves the blood-red eyes’ perceptibility without adding perfect clarity."
    },
    {
      "hunk_id": "H100",
      "decision": "SOL",
      "reason": "SOL retains the storm of blood and the monster standing beyond it."
    },
    {
      "hunk_id": "H101",
      "decision": "SOL",
      "reason": "“Come to me of your own accord” preserves the taunt that he came voluntarily when he should have fled."
    },
    {
      "hunk_id": "H102",
      "decision": "SOL",
      "reason": "SOL makes clear that the Blood Lord smiled at all three while preserving their positions and exhaustion."
    },
    {
      "hunk_id": "H103",
      "decision": "SOL",
      "reason": "“Now” preserves the transition to the threat of death."
    }
  ]
}

